REVOKE SELECT ON public.municipal_mandates FROM authenticated;
GRANT SELECT(id,election_id,candidacy_id,city_id,function,starts_at,ends_at,status,decision_id,priorities,opening_indicators,closing_indicators,governance_initialized_at,final_report) ON public.municipal_mandates TO authenticated;
REVOKE SELECT ON public.municipal_council_groups FROM authenticated; GRANT SELECT(id,mandate_id,organization_id,name,seats,majority,ideology,leader_id,base_support) ON public.municipal_council_groups TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.election_state()'::regprocedure) INTO def;def:=replace(def,'(SELECT to_jsonb(m) FROM public.municipal_mandates m WHERE m.election_id=e.id)','(SELECT to_jsonb(m)-''opening_politics''-''closing_politics'' FROM public.municipal_mandates m WHERE m.election_id=e.id)');EXECUTE def;END $$;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.governance_owner(uuid)'::regprocedure) INTO def;def:=replace(def,'PERFORM pg_advisory_xact_lock(hashtextextended(''civic:''||m.city_id,0));','PERFORM pg_advisory_xact_lock(hashtextextended(''civic:''||m.city_id,0)); SELECT * INTO m FROM public.municipal_mandates WHERE id=_mandate FOR UPDATE; IF m.status<>''active'' OR public.game_now()>=m.ends_at OR EXISTS(SELECT 1 FROM public.municipal_mandates other WHERE other.city_id=m.city_id AND other.starts_at>m.starts_at AND other.starts_at<=public.game_now()) THEN RAISE EXCEPTION ''Mandat expiré''; END IF;');EXECUTE def;END $$;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.settle_governance_politics(uuid)'::regprocedure) INTO def;def:=replace(def,'dd.completed_at IS NOT NULL AND dd.political_settled_at IS NULL','dd.funded_at IS NOT NULL AND dd.completed_at IS NOT NULL AND dd.political_settled_at IS NULL');EXECUTE def;END $$;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.abandon_municipal_dossier(uuid)'::regprocedure) INTO def;def:=replace(def,'UPDATE public.public_decisions SET workflow=''abandoned'',completed_at=public.game_now() WHERE id=d.id;','UPDATE public.public_decisions SET workflow=''abandoned'',completed_at=public.game_now() WHERE id=d.id; IF d.issue_id IS NOT NULL THEN UPDATE public.public_issues SET governance_managed=false WHERE id=d.issue_id AND issue_key NOT LIKE ''governance:%''; END IF;');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.reserve_municipal_event(_decision_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;c public.characters;d public.public_decisions;oe uuid;org uuid;loc uuid;title text;BEGIN cid:=public.prepare_daily_life();SELECT * INTO c FROM public.characters WHERE id=cid; SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id AND city_id=c.city_id AND funded_at IS NOT NULL;IF NOT FOUND THEN RAISE EXCEPTION 'Événement municipal inaccessible'; END IF;
SELECT id,location_id INTO org,loc FROM public.organizations WHERE city_id=c.city_id AND kind='citizen' AND status='active' ORDER BY id LIMIT 1;
IF NOT EXISTS(SELECT 1 FROM public.memberships WHERE character_id=cid AND organization_id=org AND status='active') THEN RAISE EXCEPTION 'Rejoignez l’association citoyenne pour participer';END IF;
title:=CASE WHEN d.workflow='completed' THEN 'Inauguration — ' ELSE 'Réunion publique — ' END||d.title;
SELECT id INTO oe FROM public.organization_events WHERE institution_id=d.institution_id AND organization_id=org AND organization_events.title=title;
IF oe IS NULL THEN INSERT INTO public.organization_events(organization_id,title,description,location_id,institution_id,civic) VALUES(org,title,'Rencontre avec les habitants autour du projet municipal. Les relations et récompenses utilisent les règles citoyennes existantes.',loc,d.institution_id,true) RETURNING id INTO oe; END IF;
RETURN public.reserve_social_event(oe);END $$;
REVOKE ALL ON FUNCTION public.reserve_municipal_event(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.reserve_municipal_event(uuid) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.governance_state()'::regprocedure) INTO def;def:=replace(def,'''rule_snapshot''','''rule_snapshot'''); EXECUTE def;END $$;